import { Schema, model, Document, Types } from 'mongoose';

/**
 * Alert generated by the anomaly detection pipeline when a sensor reading
 * breaches z-score or trend thresholds. Stored with duplicate suppression:
 * only one unresolved alert per (machine, parameter, severity) combination.
 */

export interface IAlert extends Document {
  _id: Types.ObjectId;
  machine: string;
  parameter: 'temperature' | 'vibration' | null;
  zScore: number | null;
  trendDirection: 'increasing' | 'decreasing' | 'stable' | null;
  severity: 'normal' | 'warning' | 'critical';
  message: string;
  recommendation: string;
  triggeredAt: number; // Unix epoch milliseconds
  resolved: boolean;
  resolvedAt: number | null; // Unix epoch milliseconds
  // Optional forward-links into the existing case/failure/maintenance model
  // (step 3). These never create a parallel structure — they point at the real
  // MaintenanceCase / FailureRecord / MaintenanceRecord documents.
  linkedMaintenanceCase: Types.ObjectId | null;
  linkedFailureRecord: Types.ObjectId | null;
  linkedMaintenanceRecord: Types.ObjectId | null;
  /** Optional tag for seeded/fabricated data so it can be cleaned idempotently. */
  seedTag?: string;
}

const alertSchema = new Schema<IAlert>(
  {
    machine: { type: String, required: true, index: true },
    parameter: { type: String, enum: ['temperature', 'vibration'], default: null },
    zScore: { type: Number, default: null },
    trendDirection: { type: String, default: null },
    severity: { type: String, enum: ['normal', 'warning', 'critical'], required: true },
    message: { type: String, required: true },
    recommendation: { type: String, required: true },
    triggeredAt: { type: Number, required: true, index: true },
    resolved: { type: Boolean, default: false, index: true },
    resolvedAt: { type: Number, default: null },
    linkedMaintenanceCase: { type: Schema.Types.ObjectId, ref: 'MaintenanceCase', default: null },
    linkedFailureRecord: { type: Schema.Types.ObjectId, ref: 'FailureRecord', default: null },
    linkedMaintenanceRecord: { type: Schema.Types.ObjectId, ref: 'MaintenanceRecord', default: null },
    seedTag: { type: String, default: undefined, trim: true }
  },
  { timestamps: true }
);

alertSchema.index({ machine: 1, resolved: 1, triggeredAt: -1 });
alertSchema.index({ machine: 1, parameter: 1, resolved: 1 });

/**
 * Partial unique index: only one unresolved alert per (machine, parameter, severity).
 * Duplicate-key errors from concurrent inserts are treated as "suppressed" by the
 * ingestion route (catch E11000 and skip).
 */
alertSchema.index(
  { machine: 1, parameter: 1, severity: 1 },
  { unique: true, partialFilterExpression: { resolved: false } }
);

export const Alert = model<IAlert>('Alert', alertSchema);